CREATE TABLE IF NOT EXISTS business_has_appointments (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, enabled BOOLEAN NOT NULL, `name` VARCHAR(512) NOT NULL, address VARCHAR(512) NOT NULL, time_zone VARCHAR(256) NOT NULL, working_days TINYINT DEFAULT 62 NOT NULL, source_updated_at TIMESTAMP(6) NULL);
CREATE TABLE IF NOT EXISTS appointment (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, user_id BINARY(16) NOT NULL, business_id BINARY(16) NOT NULL, employee_id BINARY(16) NOT NULL, employee_name VARCHAR(1024) NOT NULL, client_id BINARY(16) NOT NULL, client_name VARCHAR(1024) NOT NULL, client_phone VARCHAR(24) NULL, client_email VARCHAR(512) NULL, date_start TIMESTAMP(6) NOT NULL, date_end TIMESTAMP(6) NOT NULL, note VARCHAR(2048) NOT NULL, status INT NOT NULL, cancellation_reason VARCHAR(2048) NOT NULL, CONSTRAINT fk_appointment_business_id__id FOREIGN KEY (business_id) REFERENCES business_has_appointments(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX appointment_client_id ON appointment (client_id);
CREATE INDEX appointment_date_end ON appointment (date_end);
CREATE INDEX appointment_status ON appointment (status);
ALTER TABLE appointment ADD CONSTRAINT appointment_user_id_business_id_date_start_unique UNIQUE (user_id, business_id, date_start);
CREATE TABLE IF NOT EXISTS appointment_day_offs (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, CONSTRAINT fk_appointment_day_offs_business_id__id FOREIGN KEY (business_id) REFERENCES business_has_appointments(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX appointment_day_offs_business_id ON appointment_day_offs (business_id);
CREATE INDEX appointment_day_offs_business_id_start_date ON appointment_day_offs (business_id, start_date);
CREATE TABLE IF NOT EXISTS appointment_request (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, user_id BINARY(16) NOT NULL, business_id BINARY(16) NOT NULL, employee_id BINARY(16) NOT NULL, employee_name VARCHAR(1024) NOT NULL, client_id BINARY(16) NOT NULL, client_name VARCHAR(1024) NOT NULL, client_phone VARCHAR(24) NULL, client_email VARCHAR(512) NULL, date_start TIMESTAMP(6) NOT NULL, date_end TIMESTAMP(6) NOT NULL, note VARCHAR(2048) NOT NULL, status INT NOT NULL, decline_reason VARCHAR(2048) NOT NULL, CONSTRAINT fk_appointment_request_business_id__id FOREIGN KEY (business_id) REFERENCES business_has_appointments(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX appointment_request_client_id ON appointment_request (client_id);
ALTER TABLE appointment_request ADD CONSTRAINT appointment_request_user_id_business_id_date_start_unique UNIQUE (user_id, business_id, date_start);
CREATE TABLE IF NOT EXISTS appointment_settings (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, in_between_break_in_minutes INT NOT NULL, appointment_note VARCHAR(2048) NOT NULL, automatic_approval BOOLEAN NOT NULL, CONSTRAINT fk_appointment_settings_business_id__id FOREIGN KEY (business_id) REFERENCES business_has_appointments(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE appointment_settings ADD CONSTRAINT appointment_settings_business_id_unique UNIQUE (business_id);
CREATE TABLE IF NOT EXISTS user_has_appointment_permissions (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, userId BINARY(16) NOT NULL, business_id BINARY(16) NOT NULL, permission INT NOT NULL, CONSTRAINT fk_user_has_appointment_permissions_business_id__id FOREIGN KEY (business_id) REFERENCES business_has_appointments(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE user_has_appointment_permissions ADD CONSTRAINT user_has_appointment_permissions_userId_business_id_unique UNIQUE (userId, business_id);
CREATE TABLE IF NOT EXISTS working_hours (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, business_id BINARY(16) NOT NULL, day_of_week TINYINT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, CONSTRAINT fk_working_hours_business_id__id FOREIGN KEY (business_id) REFERENCES business_has_appointments(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX working_hours_business_id ON working_hours (business_id);
CREATE TABLE IF NOT EXISTS appointment_request_services (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, appointment_request_id BINARY(16) NOT NULL, service_id BINARY(16) NOT NULL, service_name VARCHAR(1024) NOT NULL, service_group_id BINARY(16) NOT NULL, price_currency VARCHAR(3) NOT NULL, price_unscaled BIGINT NOT NULL, price_scale INT NOT NULL, duration_minutes BIGINT NOT NULL, CONSTRAINT fk_appointment_request_services_appointment_request_id__id FOREIGN KEY (appointment_request_id) REFERENCES appointment_request(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX appointment_request_services_appointment_request_id ON appointment_request_services (appointment_request_id);
CREATE INDEX appointment_request_services_service_id ON appointment_request_services (service_id);
CREATE TABLE IF NOT EXISTS appointment_services (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, appointment_id BINARY(16) NOT NULL, service_id BINARY(16) NOT NULL, service_name VARCHAR(1024) NOT NULL, service_group_id BINARY(16) NOT NULL, price_currency VARCHAR(3) NOT NULL, price_unscaled BIGINT NOT NULL, price_scale INT NOT NULL, duration_minutes BIGINT NOT NULL, CONSTRAINT fk_appointment_services_appointment_id__id FOREIGN KEY (appointment_id) REFERENCES appointment(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX appointment_services_appointment_id ON appointment_services (appointment_id);
CREATE INDEX appointment_services_service_id ON appointment_services (service_id);
